      "reason": "A fire-fighting vehicle admitted by these words must also be a human-powered wheeled riding device carrying the proposed included ru.bicycle."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The words “except a moped” expressly exclude the jurisdictionally classified moped class."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "Any motor-vehicle member admitted despite the moped exception must satisfy the human-powered wheeled riding-device contract of the proposed included ru.bicycle."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "Any admitted motorcycle must satisfy the human-powered wheeled riding-device contract of the proposed included ru.bicycle, with mopeds expressly excepted."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official or contracted service supplies no independent admission, and every admitted member must also carry the proposed included ru.bicycle."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The pedestrian contract describes a person, including a person using a wheelchair or qualifying device, whereas the definition admits the riding device itself."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "This contract describes a pedestrian person rather than a device upon which a person may ride."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "Any on-track equipment admitted by the definition must also satisfy the human-powered wheeled riding-device contract of the proposed included ru.bicycle."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "School-bus designation supplies no independent admission, and any admitted member must also satisfy the contract of the proposed included ru.bicycle."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "Any marked passenger vehicle for hire admitted by the definition must also satisfy the human-powered wheeled riding-device contract of the proposed included ru.bicycle."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Any admitted tour bus, shuttle bus or limousine must also satisfy the human-powered wheeled riding-device contract of the proposed included ru.bicycle."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "Any drawn vehicle or combination admitted by the definition must itself satisfy the human-powered wheeled riding-device contract of the proposed included ru.bicycle."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "Transit service supplies no independent admission, and any admitted member must also satisfy the contract of the proposed included ru.bicycle."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "Any goods-carrying motor vehicle admitted by the definition must also satisfy the human-powered wheeled riding-device contract of the proposed included ru.bicycle."
    }
  ]
}

